import {quote as q} from './validation.js';
const text=(name,label,defaultValue,help,required=true)=>({name,label,type:'text',default:defaultValue,help,required});
const number=(name,label,defaultValue,min,max,help)=>({name,label,type:'number',default:defaultValue,min,max,help,required:true});
const bool=(name,label,defaultValue,help)=>({name,label,type:'boolean',default:defaultValue,help});
export const commands=[
{id:'computer',name:'Get computer information',category:'System Information',icon:'▦',description:'A snapshot of the operating system, hardware, and Windows version.',keywords:['computer information','system info','hardware','windows version','machine details'],cmdlets:'Get-ComputerInfo',parameters:[],generate:()=> 'Get-ComputerInfo | Select-Object CsName, WindowsProductName, WindowsVersion, OsArchitecture, CsTotalPhysicalMemory',requirements:'Windows; PowerShell 5.1 or 7. Some properties may require elevation.'},
{id:'disk',name:'Check disk space',category:'System Information',icon:'◫',description:'See capacity and free space for every local fixed drive.',keywords:['disk space','storage','free space','drive capacity'],cmdlets:'Get-CimInstance',parameters:[],generate:()=>`Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType = 3' |\n    Select-Object DeviceID, @{Name='SizeGB';Expression={[math]::Round($_.Size / 1GB, 2)}},\n        @{Name='FreeGB';Expression={[math]::Round($_.FreeSpace / 1GB, 2)}}`,requirements:'Windows; PowerShell 5.1 or 7; CIM cmdlets.'},
{id:'processes',name:'List running processes',category:'Processes',icon:'≋',description:'Find running processes and their current memory usage.',keywords:['running processes','tasks','process list','memory usage'],cmdlets:'Get-Process',parameters:[],generate:()=> 'Get-Process | Sort-Object WorkingSet64 -Descending |\n    Select-Object Id, ProcessName, @{Name=\'MemoryMB\';Expression={[math]::Round($_.WorkingSet64 / 1MB, 2)}}',requirements:'PowerShell 5.1 or 7. Access to some process details may require elevation.'},
{id:'services',name:'Get Windows services',category:'Windows Services',icon:'⚙',description:'List installed services with their names and current status.',keywords:['get services','list services','service status','windows services'],cmdlets:'Get-Service',parameters:[],generate:()=> 'Get-Service | Select-Object Status, Name, DisplayName',requirements:'Windows; PowerShell 5.1 or 7.'},
{id:'restart',name:'Restart a Windows service',category:'Windows Services',icon:'↻',description:'Restart a named service, with an optional remote computer.',keywords:['restart service','reboot service','restart windows service'],risk:'modify',cmdlets:'Get-Service · Restart-Service · Invoke-Command',parameters:[text('service','Service name','Spooler','Use the service name, such as Spooler, rather than its display name.'),text('computer','Target computer','','Leave blank to use the local computer.',false),bool('confirm','Ask for confirmation',true,'Adds -Confirm to require approval when the script runs.')],generate:v=>{const body=`Get-Service | Where-Object { $_.Name -eq ${q(v.service)} } |\n    Restart-Service -Confirm:$${v.confirm?'true':'false'} -ErrorAction Stop`;return v.computer.trim()?`Invoke-Command -ComputerName ${q(v.computer)} -ScriptBlock {\n    ${body.replaceAll('\n','\n    ')}\n}`:body;},requirements:'Windows; PowerShell 5.1 or 7. Usually requires administrator privileges. Remote targets require configured PowerShell remoting; interactive confirmation can be limited in remote sessions.'},
{id:'files',name:'List files in a directory',category:'File Management',icon:'▱',description:'Explore files in a folder, optionally including subfolders.',keywords:['list files','directory','folder contents','show files'],cmdlets:'Get-ChildItem',parameters:[text('path','Folder path','C:\\Users\\Public','An absolute or relative path on the machine running the script.'),bool('recurse','Include subfolders',false,'Search all folders beneath this path.')],generate:v=>`Get-ChildItem -LiteralPath ${q(v.path)} -File${v.recurse?' -Recurse':''} -ErrorAction Stop |\n    Select-Object Name, FullName, Length, LastWriteTime`,requirements:'PowerShell 5.1 or 7; permission to read the folder.'},
{id:'old-files',name:'Find older files',category:'File Management',icon:'◷',description:'Find files that have not been modified for a number of days.',keywords:['old files','older files','files older than','last modified','stale files'],cmdlets:'Get-ChildItem · Where-Object',parameters:[text('path','Folder path','C:\\Users\\Public','The folder to search. Files are only listed, never deleted.'),number('days','Older than (days)',30,1,36500,'Compare each file’s last modification time with this cutoff.'),bool('recurse','Include subfolders',true,'Search nested folders too.')],generate:v=>`Get-ChildItem -LiteralPath ${q(v.path)} -File${v.recurse?' -Recurse':''} -ErrorAction Stop |\n    Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-${Number(v.days)}) } |\n    Select-Object FullName, LastWriteTime, Length`,requirements:'PowerShell 5.1 or 7; permission to read the folder.'},
{id:'network',name:'Test network connectivity',category:'Networking',icon:'⌁',description:'Send a small set of ping requests to a hostname or IP address.',keywords:['network connectivity','ping','connection','reachable','test network'],cmdlets:'Test-Connection',parameters:[text('host','Hostname or IP','localhost','The computer or address to ping.'),number('count','Number of requests',4,1,100,'How many ICMP requests to send.')],generate:v=>`Test-Connection -ComputerName ${q(v.host)} -Count ${Number(v.count)} -ErrorAction Stop`,requirements:'PowerShell 5.1 or 7. ICMP may be blocked even when the target is online.'}
].map(c=>({...c,risk:c.risk||'read',versions:['5.1','7'],dependencies:[],...c}));
export const defaults=action=>Object.fromEntries(action.parameters.map(p=>[p.name,p.default]));
